/// Map for quick rate lookup (same as [CryptoAsset.usdPerUnit]).
Map<String, double> cryptoRatesMap() {
  final m = <String, double>{};
  for (final a in kCryptoCatalog) {
    m[a.id] = a.usdPerUnit;
  }
  return m;
}

CryptoAsset? lookupCryptoAsset(String id) {
  final u = id.toUpperCase();
  for (final a in kCryptoCatalog) {
    if (a.id == u) return a;
  }
  return null;
}

String normalizeCryptoCode(String code) {
  final u = code.toUpperCase();
  return lookupCryptoAsset(u) != null ? u : 'USD';
}
